public class RecordInputObserve62 {
 public static String observe() {
  Map<String,Object> result=new Map<String,Object>{'isTest'=>Test.isRunningTest()};
  Account saved=new Account(Name='owned saved'); insert saved;
  for(String id:new List<String>{'RI01','RI02','RI03','RI04','RI05'}) {
   try {
    String target; String parameter='records'; Object value;
    if(id=='RI01'){target='InputRecord62';value=new Account(Name='owned transient');}
    else if(id=='RI02'){target='InputRecord62';value=saved;}
    else if(id=='RI03'){target='InputContact62';value=new Contact(LastName='owned contact');}
    else if(id=='RI04'){target='InputWrapper62';value=new Account(Name='owned wrapped');}
    else {target='InputText62';value='owned scalar';}
    Invocable.Action action=Invocable.Action.createCustomAction('apex',target);
    action.setInvocationParameter(parameter,value);
    List<Invocable.Action.Result> replies=action.invoke();
    Map<String,Object> cell=new Map<String,Object>{'resultCount'=>replies.size(),'success'=>replies[0].isSuccess()};
    if(replies[0].isSuccess()) {cell.put('output',JSON.deserializeUntyped((String)replies[0].getOutputParameters().get('output')));}
    else {cell.put('errors',String.valueOf(replies[0].getErrors()));}
    result.put(id,cell);
   } catch(Exception e){result.put(id,new Map<String,Object>{'exceptionType'=>e.getTypeName(),'exceptionMessage'=>e.getMessage()});}
  }
  delete saved;
  return JSON.serialize(result);
 }
}

